import numpy as np

class HeterogeneousBasin:
    def __init__(self, dim=5):
        self.dim = dim
        # Define different scales and shapes for each dimension
        self.scales = np.array([1.0, 0.5, 2.0, 0.1, 1.5])[:dim]
        self.shapes = np.array(['quadratic', 'absolute', 'exponential', 'quadratic', 'absolute'])[:dim]

    def f(self, x):
        total = 0.0
        for i in range(self.dim):
            xi = x[i]
            scale = self.scales[i]
            shape = self.shapes[i]

            if shape == 'quadratic':
                term = (xi / scale) ** 2
            elif shape == 'absolute':
                term = np.abs(xi / scale)
            elif shape == 'exponential':
                term = np.exp(np.abs(xi / scale)) - 1
            else:
                term = 0.0

            total += term

        return total
